import sys
if sys.platform.startswith("java"):
    # Java has no DivisibilityOrder class; subclass Order with the same leq.
    from org.uacalc.lat import Order
    class _Div(Order):
        def leq(self, a, b):
            if a == 0:
                return True
            if b == 0:
                return a == 0
            return (b % a) == 0
    order = _Div()
else:
    from org.uacalc.lat import DivisibilityOrder
    order = DivisibilityOrder()

